-- LOCAL DEMONSTRATION DATA ONLY. Apply manually, never as a migration.
-- Required psql variable: owner_uuid (an existing active user UUID).
-- Deterministic fixture UUIDs and ON CONFLICT DO NOTHING preserve existing records.
-- Photographs come from the user-provided Stitch assets, served by the local gateway.
BEGIN;
SELECT set_config('kampive.demo_owner_uuid', :'owner_uuid', true);
DO $$ BEGIN
  IF current_database() <> 'kampive' THEN RAISE EXCEPTION 'Use the local kampive database'; END IF;
  IF NOT EXISTS (SELECT 1 FROM kampive.app_user WHERE uuid_app_user=current_setting('kampive.demo_owner_uuid')::uuid AND deactivated_at IS NULL)
    THEN RAISE EXCEPTION 'An existing active owner_uuid is required'; END IF;
END $$;

COMMIT;
-- No user credentials, existing records or acceptance timestamps are overwritten.
